import React from 'react';
import { Bar, Doughnut, Line } from 'react-chartjs-2';
import {
    Chart as ChartJS,
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    ArcElement,
    PointElement,
    LineElement,
    Filler
} from 'chart.js';

// Register ChartJS components
ChartJS.register(
    CategoryScale,
    LinearScale,
    BarElement,
    Title,
    Tooltip,
    Legend,
    ArcElement,
    PointElement,
    LineElement,
    Filler
);

const DonationStats = ({ stats, dashboardStats, donors, loading }) => {
    // Use real data from donors if stats not provided
    const donationsByType = {
        sheep: donors.filter(d => d.type === 'sheep').length,
        cow: donors.filter(d => d.type === 'cow').length
    };

    const donationsByStatus = {
        pending: donors.filter(d => d.status === 'pending').length,
        sending: donors.filter(d => d.status === 'sending').length,
        done: donors.filter(d => d.status === 'done').length
    };

    // Donation Type Chart data
    const typeData = {
        labels: ['Sheep', 'Cow'],
        datasets: [
            {
                data: [donationsByType.sheep, donationsByType.cow],
                backgroundColor: ['rgba(54, 162, 235, 0.6)', 'rgba(153, 102, 255, 0.6)'],
                borderColor: ['rgb(54, 162, 235)', 'rgb(153, 102, 255)'],
                borderWidth: 1,
            },
        ],
    };

    // Donation Status Chart data
    const statusData = {
        labels: ['Pending', 'Processing', 'Completed'],
        datasets: [
            {
                label: 'Donations by Status',
                data: [donationsByStatus.pending, donationsByStatus.sending, donationsByStatus.done],
                backgroundColor: [
                    'rgba(255, 206, 86, 0.6)',
                    'rgba(54, 162, 235, 0.6)',
                    'rgba(75, 192, 192, 0.6)',
                ],
                borderColor: [
                    'rgb(255, 206, 86)',
                    'rgb(54, 162, 235)',
                    'rgb(75, 192, 192)',
                ],
                borderWidth: 1,
            },
        ],
    };

    // Sample trend data (could be replaced with real data)
    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const trendData = {
        labels: days,
        datasets: [
            {
                label: 'Sheep Donations',
                data: [5, 8, 12, 7, 11, 9, 15],
                borderColor: 'rgb(54, 162, 235)',
                backgroundColor: 'rgba(54, 162, 235, 0.5)',
                tension: 0.3,
            },
            {
                label: 'Cow Donations',
                data: [2, 3, 5, 4, 6, 4, 7],
                borderColor: 'rgb(153, 102, 255)',
                backgroundColor: 'rgba(153, 102, 255, 0.5)',
                tension: 0.3,
            },
        ],
    };

    // If loading, show a spinner
    if (loading) {
        return (
            <div className="bg-white rounded-xl shadow-md p-6 flex justify-center items-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-500"></div>
                <p className="ml-3 text-gray-500">Loading donation statistics...</p>
            </div>
        );
    }

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            {/* Donation Types */}
            <div className="bg-gradient-to-br from-white to-blue-50 rounded-xl border-2 border-blue-200 shadow-md p-6">
                <h3 className="text-lg font-medium text-gray-800 mb-4 border-b border-blue-100 pb-2">Donation Types</h3>
                <div className="h-64 flex items-center justify-center">
                    <Doughnut
                        data={typeData}
                        options={{
                            plugins: {
                                legend: {
                                    position: 'bottom',
                                }
                            },
                            responsive: true,
                            maintainAspectRatio: false,
                        }}
                    />
                </div>
                <div className="mt-4 grid grid-cols-2 gap-2">
                    <div className="bg-blue-100 p-2 rounded text-center">
                        <p className="text-sm text-blue-700">Sheep</p>
                        <p className="font-bold text-blue-900">{donationsByType.sheep}</p>
                    </div>
                    <div className="bg-purple-100 p-2 rounded text-center">
                        <p className="text-sm text-purple-700">Cow</p>
                        <p className="font-bold text-purple-900">{donationsByType.cow}</p>
                    </div>
                </div>
            </div>

            {/* Donation Status */}
            <div className="bg-gradient-to-br from-white to-green-50 rounded-xl border-2 border-green-200 shadow-md p-6">
                <h3 className="text-lg font-medium text-gray-800 mb-4 border-b border-green-100 pb-2">Donation Status</h3>
                <div className="h-64">
                    <Bar
                        data={statusData}
                        options={{
                            plugins: {
                                legend: {
                                    display: false,
                                }
                            },
                            responsive: true,
                            maintainAspectRatio: false,
                            scales: {
                                y: {
                                    beginAtZero: true
                                }
                            }
                        }}
                    />
                </div>
                <div className="mt-4 grid grid-cols-3 gap-2">
                    <div className="bg-yellow-100 p-2 rounded text-center">
                        <p className="text-sm text-yellow-700">Pending</p>
                        <p className="font-bold text-yellow-900">{donationsByStatus.pending}</p>
                    </div>
                    <div className="bg-blue-100 p-2 rounded text-center">
                        <p className="text-sm text-blue-700">Processing</p>
                        <p className="font-bold text-blue-900">{donationsByStatus.sending}</p>
                    </div>
                    <div className="bg-green-100 p-2 rounded text-center">
                        <p className="text-sm text-green-700">Completed</p>
                        <p className="font-bold text-green-900">{donationsByStatus.done}</p>
                    </div>
                </div>
            </div>

            {/* Donation Trends */}
            <div className="lg:col-span-2 bg-gradient-to-br from-white to-amber-50 rounded-xl border-2 border-amber-200 shadow-md p-6">
                <h3 className="text-lg font-medium text-gray-800 mb-4 border-b border-amber-100 pb-2">Donation Trends</h3>
                <div className="h-80">
                    <Line
                        data={trendData}
                        options={{
                            responsive: true,
                            maintainAspectRatio: false,
                            scales: {
                                y: {
                                    beginAtZero: true
                                }
                            }
                        }}
                    />
                </div>
            </div>
        </div>
    );
};

export default DonationStats;
